  "for-professionals": {
    "title": "For Professionals",
    "url": "/for-professionals/",
    "seoTitle": "Professional Home Care Referrals Nottingham | MoreLoved Care",
    "metaDescription": "Refer to MoreLoved Care for assessed home care and Personal care in Nottingham. Review scope, referral information, quality and secure submission routes.",
    "audience": "Social workers, NHS professionals, brokers, commissioners and partner organisations",
    "intent": "Establish provider fit, understand the current service scope and submit a complete referral.",
    "heroHeading": "A clear professional route from referral to decision",
    "intro": "Professionals need an accurate view of what a provider can deliver, what information is required and how quickly the referral will be considered. MoreLoved Care separates current provision from services still in development and records the basis of each suitability decision.",
    "sections": [
      {
        "heading": "Current referral scope",
        "text": "MoreLoved Care can consider Personal care and wider homecare support for adults and approved children and young people’s packages in Nottingham and agreed areas of Nottinghamshire. Current pages explain support for older people, dementia, physical disabilities, non-clinical mental health-related needs, medication, daily living, respite, extended support and hospital discharge."
      },
      {
        "heading": "What we need from referrers",
        "text": "Provide accurate identifiers, postcode, requested start date, assessed outcomes and hours, funding authority, current risks, medication, mobility, communication, capacity or representative information, home access, equipment, professional contacts and relevant documents. Conditional questions reduce unnecessary disclosure."
      },
      {
        "heading": "How referrals are screened",
        "text": "We consider registration and service scope, required tasks and skills, geography, urgency, staffing, environment, equipment, information quality, funding and risk. A request can progress to assessment, require clarification or be declined with reasons."
      },
      {
        "heading": "Response standard",
        "text": "Professional referrals receive immediate automated acknowledgement. A member of the referral team provides a human response within four working hours during staffed hours. This confirms the next step; it does not guarantee package acceptance or mobilisation."
      },
      {
        "heading": "Secure information sharing",
        "text": "Sensitive assessments and support documents should be submitted through the approved secure referral and upload route rather than ordinary email attachments. Access is limited to authorised staff and activity is logged."
      },
      {
        "heading": "Working together",
        "text": "Where a referral is suitable, we agree assessment, mobilisation information, responsibilities, communication, reporting, review and escalation. Material changes after acceptance must be shared promptly so that suitability can be reconsidered."
      },
      {
        "heading": "Developing services",
        "text": "Supported living and specialist autism and learning disability services remain in development. They are not accepting specialist referrals or placements and should not be included in current procurement or referral assumptions."
      }
    ],
    "ctas": [
      {
        "kind": "Primary",
        "label": "Make a professional referral"
      },
      {
        "kind": "Secondary",
        "label": "Check referral criteria"
      },
      {
        "kind": "Supporting action",
        "label": "View professional documents"
      }
    ],
    "faqs": [
      {
        "q": "Can I discuss a referral before submitting documents?",
        "a": "Yes. Use the professional contact route for a preliminary discussion, particularly where scope or urgency is uncertain."
      },
      {
        "q": "Does an acknowledgement mean the package is accepted?",
        "a": "No. It confirms receipt and the next review step."
      },
      {
        "q": "Can you mobilise hospital-discharge packages urgently?",
        "a": "Urgent discharge referrals are prioritised, but mobilisation depends on complete information, assessment, staffing, equipment, funding and safe arrangements."
      },
      {
        "q": "How should sensitive documents be sent?",
        "a": "Use the secure referral upload function. Do not place health or safeguarding details in email subject lines."
      },
      {
        "q": "Can you provide commissioner assurance documents?",
        "a": "Yes. Approved public and controlled assurance materials are available through the commissioner and professional-document routes."
      }
    ],
    "category": "For Professionals",
    "breadcrumb": [
      {
        "label": "Home",
        "to": "/"
      },
      {
        "label": "For professionals",
        "to": "/for-professionals"
      }
    ]
  },
