  "recruitment-privacy-notice": {
    "title": "Recruitment Privacy Notice",
    "url": "/recruitment-privacy-notice/",
    "seoTitle": "Recruitment Privacy Notice | MoreLoved Care",
    "metaDescription": "Read how MoreLoved Care uses applicant and candidate information during recruitment, safer checks, onboarding and record retention.",
    "audience": "Applicants, candidates, referees and recruitment contacts",
    "intent": "Understand recruitment data use, special-category and criminal-record processing, sharing, retention and rights.",
    "heroHeading": "How we use information during recruitment",
    "intro": "MoreLoved Care uses candidate information to assess applications, communicate, make fair hiring decisions, complete safer-recruitment checks and prepare successful applicants for employment.",
    "sections": [
      {
        "heading": "Information collected",
        "text": "Contact details; application and CV; work and education history; qualifications; availability; interview and assessment information; right-to-work and identity evidence; references; DBS and criminal-record information where lawful; driving information; adjustment and role-suitability information; and recruitment communications."
      },
      {
        "heading": "Sources",
        "text": "Information may come from the candidate, referees, recruitment platforms, previous employers, professional or qualification bodies, DBS, right-to-work services and publicly available professional sources where lawful and relevant."
      },
      {
        "heading": "Purposes and lawful bases",
        "text": "We process information to take steps before employment, pursue legitimate recruitment and safeguarding interests, meet legal obligations, establish or defend legal claims and, where relevant, comply with employment, social-protection and substantial-public-interest conditions."
      },
      {
        "heading": "Health, disability and equality information",
        "text": "Adjustment and health information is limited to people who need it. Equality monitoring, where used, is separated from selection and normally anonymised or aggregated. Requesting an adjustment should not disadvantage the candidate."
      },
      {
        "heading": "Criminal-offence information",
        "text": "DBS and related information is processed only where the role and law permit, with appropriate policy, access, retention and secure handling. A disclosure is considered fairly and proportionately unless a legal bar applies."
      },
      {
        "heading": "Who receives information",
        "text": "Authorised recruitment and management staff, interviewers, HR support, screening providers, DBS and right-to-work services, referees, technology suppliers, legal advisers and authorities where required."
      },
      {
        "heading": "Retention",
        "text": "Application and check records are kept for the period needed to complete recruitment, respond to claims, meet legal and safeguarding duties and support onboarding. Unsuccessful-candidate information is deleted according to the approved retention schedule unless separate permission is obtained for a defined talent pool."
      },
      {
        "heading": "Successful candidates",
        "text": "Relevant recruitment information becomes part of the employment record and is then governed by employee privacy and retention arrangements."
      },
      {
        "heading": "Automated decisions",
        "text": "MoreLoved Care does not make final hiring decisions solely through automated scoring. Technology may support administration or screening, with human review of material decisions."
      },
      {
        "heading": "Your rights and contact",
        "text": "Candidates may request access, correction and other rights according to data-protection law. Contact the Data Protection Lead at the MoreLoved Care office or by the published email."
      }
    ],
    "ctas": [
      {
        "kind": "Primary",
        "label": "Contact the Data Protection Lead"
      },
      {
        "kind": "Secondary",
        "label": "View current vacancies"
      },
      {
        "kind": "Supporting action",
        "label": "Read the recruitment process"
      }
    ],
    "faqs": [
      {
        "q": "Can I withdraw an application?",
        "a": "Yes. Some information may still be retained where needed for legal, safeguarding or administrative reasons."
      },
      {
        "q": "Can you keep my CV for future jobs?",
        "a": "Only through a clear, separate retention arrangement for a defined period and purpose."
      },
      {
        "q": "Who can see an adjustment request?",
        "a": "Only staff who need the information to arrange the process or meet legal duties."
      },
      {
        "q": "Will you contact my employer without permission?",
        "a": "Reference timing and consent are explained during recruitment. Do not list a referee who should not yet be contacted without making this clear."
      },
      {
        "q": "Can I ask for interview notes?",
        "a": "You can make a data-access request. Some information may be redacted to protect other people or lawful interests."
      }
    ],
    "category": "Legal And Privacy",
    "breadcrumb": [
      {
        "label": "Home",
        "to": "/"
      },
      {
        "label": "Recruitment privacy notice",
        "to": "/recruitment-privacy-notice"
      }
    ]
  },
